/* === 民国·留声机 机密档案主题 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.=== */

/* --- 1. 字体引入 --- */
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,700;1,400&display=swap'); /* 英文复古 */
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+TC:wght@400;700&display=swap'); /* 繁体备用 */
@import url("https://fontsapi.zeoseven.com/440/main/result.css"); /* 中文全局：汇文仿宋 */
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  /* 代码块：nzgrRuYinZouZhangKai */
@import url("https://fontsapi.zeoseven.com/496/main/result.css"); /* 引号/引用：PING FANG JIANG NAN TI */
@import url("https://fontsapi.zeoseven.com/229/main/result.css"); /* 标题：临海体 */

/* --- 2. 核心颜色与变量 (深邃民国风，黑与复古金/印泥红) --- */
:root {
    --theme-bg-color: #120f0c; /* 深邃黑褐色 */
    --card-bg: #d4c5b0; /* 泛黄牛皮纸档案袋色 */
    --accent-red: #8b2500; /* 印泥暗红 */
    --accent-gold: #b38b4d; /* 怀旧黄铜金 */
    --text-main: #d9d2c5; /* 深色底上的文字 */
    --text-dark: #2c251e; /* 档案袋上的钢笔墨水色 */

    --font-en: 'Cormorant Garamond', serif;
    --font-tc: 'Noto Serif TC', serif;
    --font-main: "Huiwen-Fangsong", var(--font-en), serif;
    --font-quote: "PING FANG JIANG NAN TI", var(--font-en), serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "临海体", var(--font-en), sans-serif;
}

/* --- 3. 全局样式：无阴影、无边框、深色底 --- */
* { box-shadow: none !important; }
#sheld, #character_view { border: none !important; background: transparent !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: radial-gradient(circle at 50% 50%, rgba(30, 26, 22, 0.8) 0%, rgba(15, 12, 10, 1) 100%) !important;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
#chat { background: transparent !important; padding-bottom: 150px !important; }
h1, h2, h3, h4, h5, h6, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title) !important; color: var(--accent-gold); font-weight: normal; }
blockquote, q, em, i { font-family: var(--font-quote) !important; font-style: normal; }
code, pre { font-family: var(--font-code) !important; }

/* --- 4. 导航栏与抽屉弹窗 --- */
#top-settings-holder { 
    background-color: rgba(20, 18, 15, 0.85) !important; 
    backdrop-filter: blur(10px); 
    border-bottom: 1px solid rgba(179, 139, 77, 0.3) !important; 
}
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(20, 18, 15, 0.9), rgba(20, 18, 15, 0.95)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/TfXC/1152X656/a5e6fb252b8fe2895e6ebca591269067.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 4px !important; color: var(--text-main) !important; border: none !important;
}

/* 自定义导航栏贴图映射 */
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.3s ease; }
.drawer-icon.fa-fw:hover { transform: translateY(-3px) scale(1.1); }

.drawer-icon.fa-sliders, #ai-config-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/lOG2/1135X1134/2026-05-03%2520185011.png/webp') !important; }
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/rVKq/1233X1127/2026-05-03%2520185016.png/webp') !important; }
.drawer-icon.fa-font, #advanced-formatting-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/SV25/1179X1176/2026-05-03%2520185024.png/webp') !important; }
.drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/NlpC/1273X1258/2026-05-03%2520185035.png/webp') !important; }
.drawer-icon.fa-user, #user-settings-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/Xaby/1336X1244/2026-05-03%2520185042.png/webp') !important; }
.drawer-icon.fa-panorama, .drawer-icon.fa-image, .drawer-icon.fa-cubes, .drawer-icon.fa-bars-progress, .drawer-icon.fa-face-smile, .drawer-icon.fa-address-card, #extensions-settings-button .drawer-icon, #table_database_settings_drawer .drawer-icon, #persona-management-button .drawer-icon, #character_popup_button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/LqPi/919X920/2026-05-03%2520190237.png/webp') !important;
}
}


/* --- 5. 底部悬浮输入栏与底栏贴图 --- */
#form_sheld { position: absolute !important; bottom: 15px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { width: 90% !important; max-width: 800px !important; pointer-events: auto; }
#send_form, body.no-blur #send_form { 
    border-radius: 4px !important; 
    background-color: rgba(26, 23, 20, 0.95) !important; 
    padding: 10px 15px !important; 
    border: 1px solid #3d3126 !important; 
    transition: all 0.3s ease !important; 
}
#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { border: none !important; background: transparent !important; color: var(--text-main) !important; font-size: 1.1rem !important; font-family: var(--font-main); }
#nonQRFormItems { position: relative; }
#send_textarea::placeholder { color: transparent !important; }

/* 伪提示词 (简中) */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '录入绝密档案中... 🎙️'; 
    color: var(--accent-gold); 
    position: absolute; top: 50%; transform: translateY(-50%); left: 50px; right: 70px; 
    text-align: center; font-family: var(--font-title); font-size: clamp(1rem, 2vw, 1.2rem); 
    pointer-events: none; white-space: nowrap; overflow: hidden; 
    opacity: 0.6; animation: fade-pulse 2s infinite alternate;
}
@keyframes fade-pulse { 0% { opacity: 0.4; } 100% { opacity: 0.8; } }

/* 悬浮底栏贴图替换 */
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before, #mes_impersonate::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button, #mes_impersonate { 
    width: 36px; height: 36px; background-size: contain; background-repeat: no-repeat; background-position: center; 
    transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; 
}
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover, #mes_impersonate:hover { transform: scale(1.15) rotate(10deg); }

#options_button, #ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/QpJz/2944X2256/%25E9%25BB%2591%25E7%2599%25BD%25E6%2597%25A0%25E5%25B8%25B8%25E7%25B4%25A0%25E6%259D%2590%25E9%2593%25BA%2520%2847%29.png/webp') !important; }
#send_form #extensionsMenuButton, #auto_completion_button, #mes_impersonate { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/Z1vy/2944X2644/%25E9%25BB%2591%25E7%2599%25BD%25E6%2597%25A0%25E5%25B8%25B8%25E7%25B4%25A0%25E6%259D%2590%25E9%2593%25BA%2520%2839%29.png/webp') !important; }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/aX4d/1700X2052/%25E9%25BB%2591%25E7%2599%25BD%25E6%2597%25A0%25E5%25B8%25B8%25E7%25B4%25A0%25E6%259D%2590%25E9%2593%25BA%2520%2838%29.png/webp') !important; }

/* --- 6. 核心：消息框 (完全分离的档案室陈设) --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 80px auto 120px !important; 
    width: 90%; max-width: 800px; 
    background-color: transparent !important;
    position: relative; 
    animation: message-fade-in 0.6s ease-out; 
}
@keyframes message-fade-in { 0% { opacity: 0; transform: translateY(20px); } 100% { opacity: 1; transform: translateY(0); } }

/* 顶部风景图（独立悬挂，与正文空出距离） */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; height: 350px !important; min-height: 350px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-radius: 4px; border: none !important; 
    margin-bottom: 50px !important; /* ★ 这里是正文和顶图空出的间隙 ★ */
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/aETG/6295X3160/222.png/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/nGA4/6867X3447/111.png/webp'); }

/* 档案大照片 (跨越间隙，提升层级，向上移动) */
.mes .avatar {
    position: absolute;
    top: 260px !important; /* 向上提，防止截断 */
    width: 160px !important; height: 210px !important; 
    background: #e8ded1 !important; 
    padding: 10px 10px 40px 10px !important; 
    z-index: 100 !important; /* 提升层级，确保不会被正文盖住 */
    display: flex !important; align-items: flex-start; justify-content: center;
    border-radius: 2px !important; 
    border: 1px solid #a69b8b !important;
    transition: transform 0.4s ease, filter 0.4s ease;
}
.mes .avatar:hover {
    filter: sepia(0.2) grayscale(0) contrast(1.1) !important;
    transform: rotate(0deg) scale(1.05) !important;
    z-index: 110 !important;
}
.mes[is_user="false"] .avatar { left: 40px; transform: rotate(-4deg); }
.mes[is_user="true"] .avatar { right: 40px; left: auto; transform: rotate(4deg); }

.mes .avatar img { 
    width: 100% !important; height: 100% !important; 
    object-fit: cover !important; border-radius: 2px !important; 
    filter: sepia(0.5) grayscale(0.4) contrast(1.2); /* 老照片滤镜 */
}

/* 模拟复古回形针 */
.mes .avatar::before {
    content: '📎'; position: absolute; top: -18px; left: 20px; 
    font-size: 35px; z-index: 105; transform: rotate(15deg); filter: sepia(1);
}
/* 照片底部绝密编号 */
.mes .avatar::after {
    content: 'ARCHIVE \A 绝密照片'; white-space: pre; position: absolute;
    bottom: 8px; left: 0; right: 0; text-align: center;
    font-family: var(--font-title); font-size: 14px; color: #4a3c31; line-height: 1.2; letter-spacing: 2px;
}

/* 电脑端适配：拉大两侧距离，头像调整 */
@media (min-width: 800px) {
    .mes[is_user="false"] .avatar { left: 60px !important; }
    .mes[is_user="true"] .avatar { right: 60px !important; }
    .mes .avatar { width: 180px !important; height: 230px !important; top: 250px !important; }
}

/* --- 正文：模拟牛皮纸机密档案袋 --- */
.mes .mes_block { 
    background-color: var(--card-bg) !important; 
    padding: 50px 45px 50px 45px !important; 
    position: relative; border: none !important; border-radius: 4px;
    min-height: 150px !important; z-index: 10; 
    background-image: linear-gradient(90deg, rgba(166, 142, 105, 0.1) 0%, rgba(166, 142, 105, 0.3) 50%, rgba(166, 142, 105, 0.1) 100%) !important;
}
/* 档案袋封口红头线 */
.mes .mes_block::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; height: 8px;
    background: repeating-linear-gradient(135deg, var(--accent-red), var(--accent-red) 15px, transparent 15px, transparent 30px);
    border-radius: 4px 4px 0 0; opacity: 0.85;
}
/* 印泥盖章特效 */
.mes .mes_block::after {
    content: '【 绝 密 】'; position: absolute; bottom: 25px; right: 30px;
    color: rgba(139, 37, 0, 0.6); font-family: var(--font-title); font-size: 38px;
    border: 3px solid rgba(139, 37, 0, 0.6); padding: 6px 12px; border-radius: 4px;
    transform: rotate(-10deg); pointer-events: none; z-index: 1;
    animation: stamp-stamp 0.6s ease-out forwards;
}
.mes[is_user="true"] .mes_block::after {
    content: '【 归 档 】'; left: 30px; right: auto; transform: rotate(10deg);
}
@keyframes stamp-stamp { 0% { transform: scale(2) rotate(-15deg); opacity: 0; } 50% { transform: scale(0.9) rotate(-15deg); opacity: 1; } 100% { transform: scale(1) rotate(-15deg); opacity: 0.6; } }

/* 名字：档案袋的索引标签 (提升层级防截断) */
.mes > .ch_name, .mes .mes_block > .ch_name { 
    display: flex !important; position: absolute !important; 
    top: -42px !important; bottom: auto !important; 
    background: #b59b75 !important; border: none !important;
    border-radius: 6px 6px 0 0 !important; 
    padding: 8px 25px 12px 25px !important; 
    align-items: center !important; gap: 10px !important;
    z-index: 100 !important; /* 提升层级，防正文覆盖 */
}
.mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { left: 30px !important; right: auto !important; }
.mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { right: 30px !important; left: auto !important; }
.mes .ch_name .name_text { font-family: var(--font-title); font-size: 24px !important; letter-spacing: 2px; color: #2b231d !important; }

/* 文本样式 */
.mes .mes_text { line-height: 2.1; color: var(--text-dark); font-size: 16.5px; text-align: justify; letter-spacing: 1px; position: relative; z-index: 10 !important; }

/* 楼层/卷宗号定制 */
.mes .mesIDDisplay, .mes .mes_timer { 
    position: absolute !important; bottom: 15px !important; top: auto !important; 
    background-color: transparent !important; color: #7b6855 !important; 
    font-size: 13px !important; font-family: var(--font-main) !important; 
    letter-spacing: 1px !important; white-space: nowrap; z-index: 40 !important;
    border: none !important; border-radius: 0 !important;
}
.mes .mesIDDisplay { left: 30px !important; transform: none !important; }
.mes .mes_timer { right: 30px !important; left: auto !important; transform: none !important; }
.mesIDDisplay::before { content: '档案卷宗 ─ 第 '; }
.mesIDDisplay::after { content: ' 卷'; }

/* --- 7. 思维链 (留声机动效推演) --- */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; padding: 0 !important; margin-bottom: 12px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "🎞️ 留声机运转中，正在推演情报..."; 
    font-family: var(--font-title); font-size: 18px !important; 
    color: var(--accent-red); visibility: visible; letter-spacing: 1px; 
    animation: pulse-text 2s infinite alternate;
}
@keyframes pulse-text { 0% { opacity: 0.7; } 100% { opacity: 1; } }
.mes_reasoning { padding-left: 18px !important; margin-bottom: 25px !important; color: #4a3c31; font-family: var(--font-quote); font-size: 1.05em; position: relative; }
.mes_reasoning::before { content: ''; position: absolute; left: 0; top: 2px; bottom: 2px; width: 3px; background: var(--accent-red); opacity: 0.6; }

/* 打字指示器 (模拟转动的唱片) */
#typing_indicator { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260503/lOG2/1135X1134/2026-05-03%2520185011.png/webp') !important; 
    background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; 
    animation: spin-record 2.5s linear infinite; border: none !important; 
    height: 40px !important; width: 40px !important; margin: 15px auto !important; 
}
@keyframes spin-record { 100% { transform: rotate(360deg); } }
#typing_indicator .dot { display: none !important; }

/* 悬浮编辑按钮 */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; opacity: 0; transition: opacity 0.4s ease; pointer-events: auto !important; margin-top: 15px; position: relative; z-index: 15; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: transparent !important; color: #5a4b3c !important; padding: 4px !important; border-radius: 0 !important; cursor: pointer; transition: all 0.3s ease; font-size: 16px !important; border: none !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { color: var(--accent-red) !important; transform: scale(1.1); }

/* --- 8. 全局表单与细节修复 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { 
    background: rgba(43, 37, 32, 0.8) !important; border-radius: 2px !important; 
    padding: 12px 18px !important; margin-bottom: 10px !important; color: var(--accent-gold) !important; border: none !important; 
}
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { 
    background-color: rgba(20, 18, 15, 0.9) !important; color: var(--text-main) !important; 
    border-radius: 2px !important; padding: 10px !important; border: 1px solid #4a3c31 !important; font-family: var(--font-en); 
}
input:focus, textarea:focus, select:focus { outline: none !important; border-color: var(--accent-gold) !important; }
.menu_button { background-color: rgba(43, 37, 32, 0.8) !important; color: var(--accent-gold) !important; transition: all 0.3s ease; border-radius: 2px !important; border: none !important; }
.menu_button:hover, .menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-red) !important; color: white !important; transform: translateY(-1px); }

/* --- 9. 手机端适配收缩 --- */
@media (max-width: 768px) {
    .mes { margin: 60px auto 80px !important; }
    .mes .mesAvatarWrapper { height: 200px !important; min-height: 200px !important; margin-bottom: 40px !important; }
    .mes .avatar { width: 110px !important; height: 140px !important; top: 140px !important; padding: 6px 6px 25px 6px !important; }
    .mes[is_user="false"] .avatar { left: 15px !important; }
    .mes[is_user="true"] .avatar { right: 15px !important; }
    .mes .mes_block { padding: 40px 20px 40px 20px !important; }
    .mes > .ch_name, .mes .mes_block > .ch_name { top: -32px !important; font-size: 16px !important; padding: 4px 12px 8px 12px !important; }
    .mes[is_user="false"] > .ch_name { left: 10px !important; }
    .mes[is_user="true"] > .ch_name { right: 10px !important; }
    .mes .mesIDDisplay { left: 10px !important; }
    .mes .mes_timer { right: 10px !important; }
    .mes .mes_block::after { font-size: 28px; bottom: 10px; right: 10px; }
}
/* =======================================
   修复：头像与姓名截断问题、位置和层级提升
======================================= */

/* 核心修复：强制允许消息框和正文内容溢出，防止挂在边缘的头像和姓名被“切掉” */
.mes, .mes .mes_block {
    overflow: visible !important; 
}

/* 1. 将大照片（头像）往上提，并赋予超高层级 */
.mes .avatar {
    top: 250px !important; /* 从原本的 310px 往上提，卡在更靠上的位置 */
    z-index: 150 !important; /* 拔高层级，绝对不会被正文盖住 */
}

/* 电脑大屏端头像上移适配 */
@media (min-width: 800px) {
    .mes .avatar { 
        top: 80px !important;
    }
}

/* 手机端头像上移适配 */
@media (max-width: 768px) {
    .mes .avatar { 
        top: 60px !important; /* 从原本的 170px 往上提 */
    }
}

/* 2. 提升姓名的层级，确保它稳稳压在档案袋的最上面 */
.mes > .ch_name, .mes .mes_block > .ch_name { 
    z-index: 100 !important; /* 层级从15提升至100 */
}
